int numParticles = positions.size();
for (int i = 0; i < numParticles; i++) {
    forces[i] = std::vector<double>(3, 0.0);
    for (int j = 0; j < numParticles; j++) {
        if (i != j) {
            vec3 displacement = positions[j] - positions[i];
            // Apply periodic boundary conditions
            for (int k = 0; k < 3; k++) {
                displacement[k] -= boxSize * std::round(displacement[k] / boxSize);
            }
            double distanceSquared = std::pow(displacement[0], 2) + std::pow(displacement[1], 2) + std::pow(displacement[2], 2);
            if (distanceSquared < std::pow(cutoffRadius, 2)) {
                double distance = std::sqrt(distanceSquared);
                double ljForce = 24 * epsilon * (-2 * std::pow(sigma, 12) / std::pow(distance, 13) + std::pow(sigma, 6) / std::pow(distance, 7));
                vec3 forceDirection = displacement / distance;
                vec3 force = forceDirection * ljForce;
                forces[i][0] += force[0];
                forces[i][1] += force[1];
                forces[i][2] += force[2];
            }
        }
    }
}

